package org.sleepwell.app;
import org.json.*;

final class AlarmSoundModeJson {
    static JSONObject encode(AlarmSoundMode value){try{return new JSONObject().put("mode",value.kind.name()).put("shuffle",value.shuffle).put("tracks",new JSONArray(value.tracks)).put("names",new JSONObject(value.names));}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
    static AlarmSoundMode decode(Object raw)throws JSONException{if(!(raw instanceof JSONObject object)||(object.length()!=3&&object.length()!=4)||object.length()==4&&!object.has("names")||!(object.get("mode") instanceof String)||!(object.get("shuffle") instanceof Boolean))throw new JSONException("Invalid sound mode");try{JSONArray array=object.getJSONArray("tracks");if(array.length()>8)throw new IllegalArgumentException("Too many sounds");java.util.List<String> tracks=new java.util.ArrayList<>();for(int n=0;n<array.length();n++){Object value=array.get(n);if(!(value instanceof String))throw new IllegalArgumentException("Invalid sound");tracks.add((String)value);}java.util.Map<String,String> names=new java.util.HashMap<>();if(object.has("names")){JSONObject named=object.getJSONObject("names");if(named.length()>8)throw new IllegalArgumentException("Too many sound names");for(java.util.Iterator<String> keys=named.keys();keys.hasNext();){String key=keys.next();Object value=named.get(key);if(!(value instanceof String))throw new IllegalArgumentException("Invalid sound name");names.put(key,(String)value);}}return new AlarmSoundMode(AlarmSoundMode.Kind.valueOf(object.getString("mode")),tracks,object.getBoolean("shuffle"),names);}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}}
}
